3	/// <summary>
4	/// ITP101: a component must not publish more than one topic. Every <c>Publishes</c> call
5	/// records the single <c>default</c> output port; multi-output components (named ports)
6	/// are not part of the minimal model.
7	/// </summary>
8	internal sealed class DuplicatePortRule : ITopologyRule
9	{
10	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
11	    {
12	        foreach (var component in context.Builder.Components)
13	        {
14	            if (component.PublishCalls.Count > 1)
15	            {
16	                yield return new TopologyDiagnostic(
17	                    "ITP101",
18	                    DiagnosticSeverity.Error,
19	                    $"The component declares {component.PublishCalls.Count} Publishes calls; a component publishes exactly one topic.",
20	                    component.Name);
21	            }
22	        }
23	    }
24	}
25	
26	/// <summary>ITP102: a component must not subscribe to the same topic more than once.</summary>
27	internal sealed class DuplicateSubscriptionRule : ITopologyRule
28	{
29	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
30	    {
31	        foreach (var component in context.Builder.Components)
32	        {
33	            var duplicates = component.SubscribeCalls
34	                .GroupBy(t => (t.PubSubName, t.TopicName))
35	                .Where(g => g.Count() > 1);
36	
37	            foreach (var group in duplicates)
38	            {
39	                yield return new TopologyDiagnostic(
40	                    "ITP102",
41	                    DiagnosticSeverity.Error,
42	                    $"The topic '{group.Key.TopicName}' on pubsub '{group.Key.PubSubName}' is subscribed to more than once by the same component.",
43	                    component.Name);
44	            }
45	        }
46	    }
47	}
48	
49	/// <summary>ITP103: one topic must not be used with two different event contract types.</summary>
50	internal sealed class TopicContractConflictRule : ITopologyRule
51	{
52	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
53	    {
54	        var usages = context.Builder.Components.SelectMany(TopicUsages);
55	
56	        var conflicts = usages
57	            .GroupBy(t => (t.PubSubName, t.TopicName))
58	            .Where(g => g.Select(t => t.ContractType).Distinct().Count() > 1);
59	
60	        foreach (var group in conflicts)
61	        {
62	            var contracts = string.Join(
63	                ", ",
64	                group.Select(t => t.ContractType.FullName ?? t.ContractType.Name).Distinct().Order(StringComparer.Ordinal));
65	            yield return new TopologyDiagnostic(
66	                "ITP103",
67	                DiagnosticSeverity.Error,
68	                $"The topic '{group.Key.TopicName}' on pubsub '{group.Key.PubSubName}' is declared with conflicting contract types: {contracts}.",
69	                group.Key.TopicName);
70	        }
71	    }
72	
73	    private static IEnumerable<TopicRef> TopicUsages(Component component)
74	    {
75	        foreach (var (_, topic) in component.PublishCalls)
76	        {
77	            yield return topic;
78	        }
79	
80	        foreach (var topic in component.SubscribeCalls)
81	        {
82	            yield return topic;
83	        }
84	    }
85	}
86	
87	/// <summary>ITP104: one connector name must not be declared with two different transports.</summary>
88	internal sealed class ConnectorConflictRule : ITopologyRule
89	{
90	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
91	    {
92	        var usages = context.Builder.Components.SelectMany(ConnectorUsages);
93	
94	        foreach (var group in usages.GroupBy(c => c.Name, StringComparer.Ordinal))
95	        {
96	            var transports = group
97	                .Select(c => (Local: c.Transport, Deployed: c.DeployedTransport))
98	                .Distinct()
99	                .ToArray();
100	            if (transports.Length > 1)
101	            {
102	                var transportTypes = transports
103	                    .Select(t => t.Deployed is null
104	                        ? t.Local.DaprType
105	                        : $"{t.Local.DaprType} (deployed: {t.Deployed.DaprType})")
106	                    .Distinct(StringComparer.Ordinal)
107	                    .Order(StringComparer.Ordinal);
108	                yield return new TopologyDiagnostic(
109	                    "ITP104",
110	                    DiagnosticSeverity.Error,
111	                    $"The connector '{group.Key}' is declared with conflicting transports: {string.Join(", ", transportTypes)}.",
112	                    group.Key);
113	            }
114	        }
115	    }
116	
117	    private static IEnumerable<ConnectorRef> ConnectorUsages(Component component)
118	    {
119	        foreach (var (connector, _) in component.ConnectorCalls)
120	        {
121	            yield return connector;
122	        }
123	    }
124	}
125	
126	/// <summary>
127	/// ITP211: an explicitly declared deployed transport must support every connector direction
128	/// used by the component. A connector without a deployed transport continues to use its local
129	/// transport for deployment and needs no additional validation.
130	/// </summary>
131	internal sealed class DeployedTransportCapabilityRule : ITopologyRule
132	{
133	    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
134	    {
135	        foreach (var component in context.Builder.Components)
136	        {
137	            foreach (var (connector, direction) in component.ConnectorCalls)
138	            {
139	                var transport = connector.DeployedTransport;
140	                if (transport is null || Supports(direction, transport))
141	                {
142	                    continue;
143	                }
144	
145	                var operation = direction == Intropy.Topology.Model.ConnectorDirection.In ? "From" : "To";
146	                var capability = direction == Intropy.Topology.Model.ConnectorDirection.In ? "input" : "output";
147	                yield return new TopologyDiagnostic(
148	                    "ITP211",
149	                    DiagnosticSeverity.Error,
150	                    $"The connector '{connector.Name}' declares deployed transport '{transport.DaprType}', which does not support {capability} required by {operation}.",
151	                    component.Name);
152	            }
153	        }
154	    }
155	
156	    private static bool Supports(Intropy.Topology.Model.ConnectorDirection direction, Transport transport) =>
157	        direction == Intropy.Topology.Model.ConnectorDirection.In ? transport.SupportsInput : transport.SupportsOutput;
158	}
