}

public class ScheduleExpressionRuleTests
{
    [Theory]
    [InlineData("not a cron")]
    [InlineData("* * * * * *")]
    [InlineData("@fortnightly")]
    public void Validate_WithInvalidCron_ShouldReportItp210(string cron)
    {
