using Intropy.Topology.Model;

namespace Intropy.Topology.Test.Building;

public class BuilderMappingTests
{
    [Fact]
    public void AddComponent_PerKind_ShouldMapComponentKindAndDeclarationOrder()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("a").Publishes(TestTopics.Raw);
        s.AddLoader("d").Subscribes(TestTopics.Raw).To(TestConnectors.Erp);
        s.AddTransactionalIntegration("e").From(TestConnectors.Pim);

        // Act
        var topology = s.Build();

        // Assert
        Assert.Equal(["a", "d", "e"], topology.Components.Select(w => w.Name));
        Assert.Equal(
            [
                ComponentKind.Extractor,
                ComponentKind.Loader,
                ComponentKind.TransactionalIntegration,
            ],
            topology.Components.Select(w => w.Kind));
    }

    [Fact]
    public void Subscribes_OnLoader_ShouldRecordSingleSubscription()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddLoader("loader").Subscribes(TestTopics.Raw).To(TestConnectors.Erp);
        s.AddExtractor("source").Publishes(TestTopics.Raw);

        // Act
        var component = s.Build().Components[0];

        // Assert
        var subscription = Assert.Single(component.Subscribes);
        Assert.Equal("test-pubsub", subscription.PubSubName);
        Assert.Equal("raw-events", subscription.TopicName);
    }

    [Fact]
    public void From_ShouldRecordInEdge()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("extractor").From(TestConnectors.Pim).Publishes(TestTopics.Raw);
        s.AddLoader("sink").Subscribes(TestTopics.Raw);

        // Act
        var component = s.Build().Components[0];

        // Assert
        var edge = Assert.Single(component.Connectors);
        Assert.Equal("pim", edge.ConnectorName);
        Assert.Equal(ConnectorDirection.In, edge.Direction);
    }

    [Fact]
    public void Publishes_ShouldUseDefaultPort()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("extractor").Publishes(TestTopics.Raw);
        s.AddLoader("sink").Subscribes(TestTopics.Raw);

        // Act
        var edge = s.Build().Components[0].Publishes.Single();

        // Assert
        Assert.Equal("default", edge.Port);
        Assert.Equal("test-pubsub", edge.PubSubName);
        Assert.Equal("raw-events", edge.TopicName);
    }

    [Fact]
    public void FromAndTo_ShouldMapDirections()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddTransactionalIntegration("ti")
            .From(TestConnectors.Pim)
            .To(TestConnectors.Erp);

        // Act
        var component = s.Build().Components.Single();

        // Assert
        Assert.Equal(
            [("pim", ConnectorDirection.In), ("erp", ConnectorDirection.Out)],
            component.Connectors.Select(c => (c.ConnectorName, c.Direction)));
    }

    [Fact]
    public void FluentMethods_ShouldReturnSameBuilderInstance()
    {
        // Arrange: every edge call chains on the one builder Add* returned
        var s = SystemBuilder.Create("test-system");
        var builder = s.AddExtractor("extractor");

        // Assert
        Assert.Same(builder, builder.Publishes(TestTopics.Raw));
        Assert.Same(builder, builder.From(TestConnectors.Pim));
        Assert.Same(builder, builder.WithSchedule("@daily"));
    }

    [Fact]
    public void WithSchedule_ShouldRecordScheduleOnComponentModel()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("extractor").Publishes(TestTopics.Raw).WithSchedule("*/5 * * * *");
        s.AddLoader("sink").Subscribes(TestTopics.Raw);

        // Act
        var topology = s.Build();

        // Assert
        Assert.Equal("*/5 * * * *", topology.Components[0].Schedule);
        Assert.Null(topology.Components[1].Schedule);
    }

    [Fact]
    public void WithSchedule_CalledTwice_ShouldKeepLastValue()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("extractor")
            .Publishes(TestTopics.Raw)
            .WithSchedule("@hourly")
            .WithSchedule("@daily");
        s.AddLoader("sink").Subscribes(TestTopics.Raw);

        // Act & Assert
        Assert.Equal("@daily", s.Build().Components[0].Schedule);
    }

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("   ")]
    public void WithSchedule_WithNullOrWhitespace_ShouldThrowArgumentException(string? cron)
    {
        // Arrange: null/whitespace is an argument error at the call site; cron *syntax*
        // is deferred to Build() (ITP210) so all diagnostics report at once.
        var s = SystemBuilder.Create("test-system");
        var builder = s.AddExtractor("extractor");

        // Act & Assert
        Assert.ThrowsAny<ArgumentException>(() => builder.WithSchedule(cron!));
    }

    [Fact]
    public void Build_CalledTwiceAfterMutation_ShouldReflectMutation()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("extractor").Publishes(TestTopics.Raw);
        s.AddLoader("loader").Subscribes(TestTopics.Raw).To(TestConnectors.Erp);
        var first = s.Build();

        // Act
        s.AddLoader("audit").Subscribes(TestTopics.Raw);
        var second = s.Build();

        // Assert
        Assert.Equal(2, first.Components.Count);
        Assert.Equal(3, second.Components.Count);
    }

    [Theory]
    [InlineData("Bad-Name")]
    [InlineData("bad_name")]
    [InlineData("")]
    public void REDACTED(string name)
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");

        // Act & Assert
        Assert.Throws<ArgumentException>(() => s.AddExtractor(name));
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Test.Building;

public class MaterializationTests
{
    [Fact]
    public void Build_ShouldPreserveComponentDeclarationOrder()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("extractor").Publishes(TestTopics.Raw);
        s.AddTransactionalIntegration("ti").From(TestConnectors.Pim);
        s.AddLoader("loader").Subscribes(TestTopics.Raw).To(TestConnectors.Erp);

        // Act
        var topology = s.Build();

        // Assert
        Assert.Equal(["extractor", "ti", "loader"], topology.Components.Select(c => c.Name));
    }

    [Fact]
    public void Build_WithSharedTopic_ShouldMaterializeOneTopicResourceWithBothSides()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("extractor").Publishes(TestTopics.Raw);
        s.AddLoader("sink").Subscribes(TestTopics.Raw);

        // Act
        var topology = s.Build();

        // Assert
        var raw = Assert.Single(topology.Topics);
        Assert.Equal("test-pubsub", raw.PubSubName);
        Assert.Equal("raw-events", raw.TopicName);
        Assert.Equal(typeof(RawEvent).FullName, raw.ContractTypeName);
        Assert.Equal(["extractor"], raw.Publishers);
        Assert.Equal(["sink"], raw.Subscribers);
    }

    [Fact]
    public void Build_WithSameConnectorInBothDirections_ShouldMaterializeOneResourceWithBothDirections()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddTransactionalIntegration("ti")
            .From(TestConnectors.Pim)
            .To(TestConnectors.Pim);

        // Act
        var connector = s.Build().Connectors.Single();

        // Assert
        Assert.Equal("pim", connector.Name);
        Assert.Equal(Transport.File("./test/pim"), connector.Transport);
        Assert.Equal("binding.pim", connector.DaprComponentName);
        Assert.Equal([ConnectorDirection.In, ConnectorDirection.Out], connector.Directions);
        Assert.Equal(["ti"], connector.UsedBy);
    }

    [Fact]
    public void Build_WithDeployedConnectorTransport_ShouldMaterializeBothTransportProfiles()
    {
        // Arrange
        var connector = ConnectorRef.Define("pim", Transport.File("./test/pim"))
            .WithDeployed(Transport.Sftp());
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("extractor").Publishes(TestTopics.Raw);
        s.AddLoader("loader").Subscribes(TestTopics.Raw).To(connector);

        // Act
        var materialized = Assert.Single(s.Build().Connectors);

        // Assert
        Assert.Equal(Transport.File("./test/pim"), materialized.Transport);
        Assert.Equal(Transport.Sftp(), materialized.DeployedTransport);
    }

    [Fact]
    public void Build_WithDuplicateSameDirectionConnectorCalls_ShouldDedupeSilently()
    {
        // Arrange
        var s = SystemBuilder.Create("test-system");
        s.AddTransactionalIntegration("ti")
            .From(TestConnectors.Pim)
            .From(TestConnectors.Pim);

        // Act
        var topology = s.Build();

        // Assert: one edge, one resource, no diagnostics
        Assert.Single(topology.Components.Single().Connectors);
        Assert.Single(topology.Connectors);
        Assert.Empty(s.Validate());
    }

    [Fact]
    public void Build_ShouldSortResourcesDeterministically()
    {
        // Arrange: declare in non-alphabetical order
        var erp = ConnectorRef.Define("erp", Transport.File("./test/erp"));
        var s = SystemBuilder.Create("test-system");
        s.AddExtractor("zeta")
            .Publishes(TopicRef<RawEvent>.Define("test-pubsub", "zzz-topic"))
            .From(TestConnectors.Pim);
        s.AddExtractor("alpha")
            .Publishes(TopicRef<RawEvent>.Define("test-pubsub", "aaa-topic"))
            .From(erp);
        s.AddLoader("sink-a").Subscribes(TopicRef<RawEvent>.Define("test-pubsub", "aaa-topic"));
        s.AddLoader("sink-z").Subscribes(TopicRef<RawEvent>.Define("test-pubsub", "zzz-topic"));

        // Act
        var topology = s.Build();

        // Assert
        Assert.Equal(["aaa-topic", "zzz-topic"], topology.Topics.Select(t => t.TopicName));
        Assert.Equal(["erp", "pim"], topology.Connectors.Select(c => c.Name));
    }

    // A second edge that a block cannot legally have (formerly the ITP203/204/205 family)
    // is a compile error: the block builders expose only that block's legal edge methods.
}

# Getting Started

This guide walks you through declaring the order-flow topology — an extractor and a loader sharing one topic. By the end, you'll have a runnable SystemHost that validates the declaration, prints the materialized model, and generates Dapr components. The finished result lives in [`examples/OrderFlow.SystemHost`](../examples/OrderFlow.SystemHost/), whose declaration files mirror `intropy sys create` output verbatim.

## Prerequisites

- .NET 10 SDK
- A .NET console project (the SystemHost)

## Install the package

```bash
dotnet add package Intropy.Topology
```

## Declare your topics

Topics are declared as static fields — in a `Topics.cs` for system-internal topics, or in a shared contracts package for cross-system topics. `TopicRef<T>` carries the event contract type carried on the topic:

```csharp
public static class Topics
{
    public static readonly TopicRef<Order> Orders = TopicRef<Order>.Define("pubsub", "orders");
}
```

There is no `AddTopic` on the builder — publishing to or subscribing to a topic is what brings it (and its pubsub) into the model.

## Declare your connectors

A connector is the named port an edge block reaches the outside world through. Its transport selects the Dapr binding type it materializes as; the Dapr component name is always derived from the connector's name (`binding.order-extractor-source`), never declared:

```csharp
public static class Connectors
{
    public static readonly ConnectorRef OrderExtractorSource =
        ConnectorRef.Define("order-extractor-source", Transport.File("./test/order-extractor-source"));

    public static readonly ConnectorRef OrderLoaderDestination =
        ConnectorRef.Define("order-loader-destination", Transport.File("./test/order-loader-destination"));
}
```

`Transport.File(rootPath)` (`bindings.localstorage`) makes the folder the endpoint, so the system runs with zero external configuration. Connectors are system-owned and never shared across systems. Direction is not part of the identity — it follows from usage (`From` reads, `To` writes).

## Declare the system

A system is a class implementing `ISystemDefinition`. Each `Add*` call returns the block's builder directly, exposing only the edges legal for that block:

```csharp
public sealed class OrderFlowSystem : ISystemDefinition
{
    public string SystemName => "order-flow";

    public void Define(SystemBuilder builder)
    {
        // Extractor: edge block, pulls data out through a connector and publishes it.
        builder.AddExtractor("order-extractor")
            .From(Connectors.OrderExtractorSource)
            .Publishes(Topics.Orders);

        // Loader: edge block, subscribes to exactly one topic and writes through a connector.
        builder.AddLoader("order-loader")
            .Subscribes(Topics.Orders)
            .To(Connectors.OrderLoaderDestination);
    }
}
```

A method that would be illegal for the block type does not exist on its builder — `AddLoader(...).Publishes(topic)` is a compile error, because loaders publish nothing, and `AddExtractor(...).Subscribes(topic)` does not compile, because extractors don't subscribe.

## Build and inspect

`Build()` materializes and validates the topology. It throws a `TopologyValidationException` carrying every diagnostic at once when the declaration is invalid:

```csharp
SystemTopology topology;
try
{
    topology = builder.Build();
}
catch (TopologyValidationException ex)
{
    Console.Error.WriteLine(ex.Message);
    return 1;
}
```

Use `TryBuild(out var topology, out var diagnostics)` to inspect diagnostics (including warnings) without throwing, or `Validate()` to run the rules without building.

## Wire up the entry point

The SystemHost's `Program.cs` routes one entry point to two backends of the same discovered topology:

```csharp
var assembly = Assembly.GetExecutingAssembly();

return args is ["run", ..] or []
    ? await IntropyAspire.RunAsync(assembly, args)    // → .NET Aspire + DCP (local F5)
    : await IntropyGenerate.RunAsync(assembly, args); // → generate | check | graph
```

```bash
dotnet run                       # Aspire dashboard (needs Docker + `dapr init`)
dotnet run -- check              # validate the topology
dotnet run -- graph              # print the SystemTopology JSON
dotnet run -- generate ./out     # write Dapr YAML + per-component config
```

`generate` emits `components/<pubsub>.yaml` (Redis-backed pub/sub), one `components/binding.<connector>.yaml` per connector (root path absolutized), and `config/<component>.intropy.json` per component.

